```typescript
export function requireMcpAuth(requiredTier: McpTier = 'public'): RequestHandler {
  return (req, res, next) => {
    const authHeader = req.headers.authorization;
    if (!authHeader?.startsWith('Bearer ')) return res.status(401).json({...});
    const token = authHeader.slice(7).trim();

    const publicToken = getMcpPublicToken();
    const adminToken = getMcpAdminToken();

    let tokenTier: McpTier = 'denied';
    if (publicToken && crypto.timingSafeEqual(Buffer.from(token), Buffer.from(publicToken))) tokenTier = 'public';
    else if (adminToken && crypto.timingSafeEqual(Buffer.from(token), Buffer.from(adminToken))) tokenTier = 'admin';

    if (tokenTier === 'denied') return res.status(401).json({ error: 'Invalid token', code: 'MCP_AUTH_INVALID' });

    // Admin token can call public tools too (admin >= public). Public token cannot call admin tools.
    if (requiredTier === 'admin' && tokenTier !== 'admin') {
      return res.status(403).json({
        error: 'Admin token required for this tool',
        code: 'MCP_AUTH_INSUFFICIENT_TIER',
        hint: 'Use the admin token from ~/.rorca/mcp-admin-token, or run `rorca mcp setup-claude --admin`.'
      });
    }

    (req as any).mcpTier = tokenTier;  // For audit log (CLI-051)
    next();
  };
}
```

