```typescript
export function planGate(): RequestHandler {
  return async (req, res, next) => {
    const operation = matchOperationFromRoute(req); // looks up the @swagger operation for this URL
    if (!operation) return next();  // unannotated route — handled by CLI-047 default-deny logic

    const { tier, capability } = getRorcaTier(operation);

    // Public tier — always allowed
    if (tier === 'public') return next();

    const user = await getEffectiveUser(req);

    // Auth tier — requires logged-in user
    if (tier === 'auth') {
      if (!user || user.id === 'local-admin') return next(); // LOCAL_ADMIN passes (single-user mode)
      return next();
    }

    // Paid tier — requires capability check
    if (tier === 'paid') {
      if (!capability) {
        logger.error(`[plan-gate] Paid route ${req.path} missing x-rorca-capability annotation`);
        return res.status(500).json({ error: 'Server misconfiguration', code: 'PAID_ROUTE_MISCONFIGURED' });
      }
      const userPlan = (user?.plan ?? 'free') as RorcaPlan;
      if (!planHasCapability(userPlan, capability)) {
        return res.status(402).json({
          error: 'Payment Required',
          code: 'PLAN_REQUIRED',
          requiredCapability: capability,
          currentPlan: userPlan,
          upgradeUrl: 'https://rorca.app/pricing',
          hint: `This feature requires a plan with '${capability}'. Current plan: ${userPlan}.`,
        });
      }
      return next();
    }

    // Admin tier — requires admin role
    if (tier === 'admin') {
      if (user?.role !== 'admin') {
        return res.status(403).json({ error: 'Admin role required', code: 'ADMIN_REQUIRED' });
      }
      return next();
    }

    // Denied tier (default) — return 404 to avoid leaking route existence
    return res.status(404).json({ error: 'Not found' });
  };
}
```

