```typescript
import { createVerify } from 'crypto';

const LICENSE_PUBLIC_KEY = process.env.RORCA_LICENSE_PUBLIC_KEY || EMBEDDED_PUBLIC_KEY;

export function verifyLicense(key: string): { valid: boolean; plan: RorcaPlan; expiresAt: Date | null } {
  // License format: base64url(payload).base64url(signature)
  const [payloadB64, sigB64] = key.split('.');
  if (!payloadB64 || !sigB64) return { valid: false, plan: 'free', expiresAt: null };

  const verifier = createVerify('SHA256');
  verifier.update(payloadB64);
  const isValid = verifier.verify(LICENSE_PUBLIC_KEY, Buffer.from(sigB64, 'base64url'));

  if (!isValid) return { valid: false, plan: 'free', expiresAt: null };

  const payload = JSON.parse(Buffer.from(payloadB64, 'base64url').toString());
  return { valid: true, plan: payload.plan, expiresAt: payload.expiresAt ? new Date(payload.expiresAt) : null };
}
```
The private key for license generation lives ONLY on Rorca's licensing server (not in the OSS code). The public key is embedded in the BSL backend (not in the MIT CLI). Forking the CLI doesn't give you a private key, so forks cannot generate valid license keys.

